#!/usr/bin/env bash
# T1c-F (ICD frequency bias; preregistration.md in this folder): exact queue commands. NOT EXECUTED by the agent.
# Printed by `python -m vsa_embed.experiments.t1c_icd_frequency plan`. Run from the main checkout's root after merging:
#   cd /home/bhux/workplace/VSA-LLM && PY=/home/bhux/anaconda3/envs/vsa-repro/bin/python
# The CPU stages (prepare, tokenize, kge) have run; their outputs are in ~/data/vsa-llm/t1c/icd-frequency-v1/
# (shared by every checkout) and prepare re-checks the pinned holdout if re-run.
# GPU-h: idle-GPU estimates from the smoke (§14); the smoke ran beside a training job (≈ 1.6× slower).
# Memory: ≤ 1.5 GB per job measured (encode 1.2 GB, train 1.5 GB); disk: states ≈ 12 GB per encoder, heads ≈ 1.7 GB per job.
set -euo pipefail
: "${PY:?set PY to the pinned interpreter}"

# --- pass 1: P0 = frozen SmolLM2-360M (no dependency; could run now). Priority 55 places it right after
# T1c seed 1 (51–54); a lower number would run it first. ≈ 4.1 GPU-h ---
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1cf-encode-P0-360M --priority 55 --min-free-gb 20 -- $PY -m vsa_embed.experiments.t1c_icd_frequency encode --config experiments/t1c-clinical/icd-frequency/icd-frequency.yaml --encoder P0-360M --pretrained HuggingFaceTB/SmolLM2-360M   # ≈ 1.5 GPU-h (resumable)
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1cf-train-P0-360M-s1 --priority 55 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/icd-frequency/icd-frequency.yaml --encoder P0-360M --seed 1   # 7 conditions ≈ 0.8 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1cf-train-P0-360M-s2 --priority 55 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/icd-frequency/icd-frequency.yaml --encoder P0-360M --seed 2   # 7 conditions ≈ 0.8 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1cf-train-P0-360M-s3 --priority 55 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/icd-frequency/icd-frequency.yaml --encoder P0-360M --seed 3   # 7 conditions ≈ 0.8 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1cf-analyze-P0-360M --priority 55 --min-free-gb 2 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency analyze --config experiments/t1c-clinical/icd-frequency/icd-frequency.yaml --encoder P0-360M --seeds 1 2 3 --device cuda   # ≈ 0.15 GPU-h

# --- pass 2: needs the T1c seed-1 runs SmolLM2-360M-full-C0p-s1 and -C5-s1 (queued at 51). Priority 56
# (analyses 57). ≈ 9.8 GPU-h ---
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1cf-encode-C0p-360M --priority 56 --min-free-gb 20 -- $PY -m vsa_embed.experiments.t1c_icd_frequency encode --config experiments/t1c-clinical/icd-frequency/icd-frequency.yaml --encoder C0p-360M --run experiments/e9-retrofit/runs/t1c/SmolLM2-360M-full-C0p-s1   # ≈ 1.7 GPU-h (resumable)
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1cf-train-C0p-360M-s1 --priority 56 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/icd-frequency/icd-frequency.yaml --encoder C0p-360M --seed 1 --conditions free composed_head composed_c5 transe title random gram composed_free --c5-run experiments/e9-retrofit/runs/t1c/SmolLM2-360M-full-C5-s1   # 8 conditions ≈ 0.9 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1cf-train-C0p-360M-s2 --priority 56 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/icd-frequency/icd-frequency.yaml --encoder C0p-360M --seed 2 --conditions free composed_head composed_c5 transe title random gram composed_free --c5-run experiments/e9-retrofit/runs/t1c/SmolLM2-360M-full-C5-s1   # 8 conditions ≈ 0.9 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1cf-train-C0p-360M-s3 --priority 56 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/icd-frequency/icd-frequency.yaml --encoder C0p-360M --seed 3 --conditions free composed_head composed_c5 transe title random gram composed_free --c5-run experiments/e9-retrofit/runs/t1c/SmolLM2-360M-full-C5-s1   # 8 conditions ≈ 0.9 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1cf-encode-C5-360M --priority 56 --min-free-gb 20 -- $PY -m vsa_embed.experiments.t1c_icd_frequency encode --config experiments/t1c-clinical/icd-frequency/icd-frequency.yaml --encoder C5-360M --run experiments/e9-retrofit/runs/t1c/SmolLM2-360M-full-C5-s1 --channel on   # ≈ 1.7 GPU-h (resumable)
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1cf-train-C5-360M-s1 --priority 56 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/icd-frequency/icd-frequency.yaml --encoder C5-360M --seed 1 --conditions free composed_head composed_c5 transe title random gram composed_free --c5-run experiments/e9-retrofit/runs/t1c/SmolLM2-360M-full-C5-s1   # 8 conditions ≈ 0.9 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1cf-train-C5-360M-s2 --priority 56 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/icd-frequency/icd-frequency.yaml --encoder C5-360M --seed 2 --conditions free composed_head composed_c5 transe title random gram composed_free --c5-run experiments/e9-retrofit/runs/t1c/SmolLM2-360M-full-C5-s1   # 8 conditions ≈ 0.9 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1cf-train-C5-360M-s3 --priority 56 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/icd-frequency/icd-frequency.yaml --encoder C5-360M --seed 3 --conditions free composed_head composed_c5 transe title random gram composed_free --c5-run experiments/e9-retrofit/runs/t1c/SmolLM2-360M-full-C5-s1   # 8 conditions ≈ 0.9 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1cf-train-P0-360M-c5dict-s1 --priority 56 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/icd-frequency/icd-frequency.yaml --encoder P0-360M --seed 1 --conditions composed_c5 --c5-run experiments/e9-retrofit/runs/t1c/SmolLM2-360M-full-C5-s1   # ≈ 0.15 GPU-h (same batch order as pass 1: paired)
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1cf-train-P0-360M-c5dict-s2 --priority 56 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/icd-frequency/icd-frequency.yaml --encoder P0-360M --seed 2 --conditions composed_c5 --c5-run experiments/e9-retrofit/runs/t1c/SmolLM2-360M-full-C5-s1   # ≈ 0.15 GPU-h (same batch order as pass 1: paired)
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1cf-train-P0-360M-c5dict-s3 --priority 56 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/icd-frequency/icd-frequency.yaml --encoder P0-360M --seed 3 --conditions composed_c5 --c5-run experiments/e9-retrofit/runs/t1c/SmolLM2-360M-full-C5-s1   # ≈ 0.15 GPU-h (same batch order as pass 1: paired)
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1cf-analyze-P0-360M-pass2 --priority 57 --min-free-gb 2 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency analyze --config experiments/t1c-clinical/icd-frequency/icd-frequency.yaml --encoder P0-360M --seeds 1 2 3 --device cuda --label -pass2   # ≈ 0.15 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1cf-analyze-C0p-360M-pass2 --priority 57 --min-free-gb 2 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency analyze --config experiments/t1c-clinical/icd-frequency/icd-frequency.yaml --encoder C0p-360M --seeds 1 2 3 --device cuda --label -pass2   # ≈ 0.15 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1cf-analyze-C5-360M-pass2 --priority 57 --min-free-gb 2 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency analyze --config experiments/t1c-clinical/icd-frequency/icd-frequency.yaml --encoder C5-360M --seeds 1 2 3 --device cuda --label -pass2   # ≈ 0.15 GPU-h

# optional (open decision): the C5 encoder with its channel off — reads whether a C5-encoder gain comes through the
# injected rows (§6). Then train it like C5-360M (3 seeds) and analyze with --label -pass2:
# PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1cf-encode-C5off-360M --priority 58 --min-free-gb 20 -- $PY -m vsa_embed.experiments.t1c_icd_frequency encode --config experiments/t1c-clinical/icd-frequency/icd-frequency.yaml --encoder C5off-360M --run experiments/e9-retrofit/runs/t1c/SmolLM2-360M-full-C5-s1 --channel off   # ≈ 1.7 GPU-h
